// Generated by the upstream tooling, and edited here on purpose: see the note
// on which environment variable holds the key. A regeneration will drop that
// change and break every admin-side feature again.
// Server-side Supabase client with service role key - bypasses RLS.
// Use this for admin operations in server functions and server routes only.
// For user-authenticated queries (with RLS), use the auth middleware instead.
import { createClient } from "@supabase/supabase-js";
import type { Database } from "./types";
import { isNewSupabaseApiKey, supabaseUrl } from "./config";

function createSupabaseFetch(supabaseKey: string): typeof fetch {
  return (input, init) => {
    const headers = new Headers(
      typeof Request !== "undefined" && input instanceof Request ? input.headers : undefined,
    );

    if (init?.headers) {
      new Headers(init.headers).forEach((value, key) => headers.set(key, value));
    }

    // New Supabase API keys are opaque strings, not bearer JWTs.
    if (
      isNewSupabaseApiKey(supabaseKey) &&
      headers.get("Authorization") === `Bearer ${supabaseKey}`
    ) {
      headers.delete("Authorization");
    }

    headers.set("apikey", supabaseKey);
    return fetch(input, { ...init, headers });
  };
}

function createSupabaseAdminClient() {
  const SUPABASE_URL = supabaseUrl();
  // Deliberately env-only and never given a fallback: this key bypasses row level
  // security, so it must not live in the repository or reach the client bundle.
  //
  // Two names, because the key has two.
  //
  // Supabase renamed it: the thing that used to be the service role key is now
  // the secret key, and the official Vercel integration writes it as
  // SUPABASE_SECRET_KEY. This deployment has both names present - the new one
  // holding the key, and the old one left as an empty placeholder from the
  // project's first setup - and reading only the old name found the empty one
  // and threw. Which means everything that uses this client has been failing in
  // production: the cron worker, social publishing, and the signup hook that
  // finally said so out loud.
  const SUPABASE_SERVICE_ROLE_KEY =
    process.env["SUPABASE_SERVICE_ROLE_KEY"] || process.env["SUPABASE_SECRET_KEY"];

  if (!SUPABASE_SERVICE_ROLE_KEY) {
    const message =
      "Missing SUPABASE_SERVICE_ROLE_KEY (or SUPABASE_SECRET_KEY). Set one in the host's " +
      "environment variables. Only admin-side features need it (the cron worker, " +
      "social publishing and the signup notification); the rest of the app runs without it.";
    console.error(`[Supabase] ${message}`);
    throw new Error(message);
  }

  return createClient<Database>(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, {
    global: {
      fetch: createSupabaseFetch(SUPABASE_SERVICE_ROLE_KEY),
    },
    auth: {
      storage: undefined,
      persistSession: false,
      autoRefreshToken: false,
    },
  });
}

let _supabaseAdmin: ReturnType<typeof createSupabaseAdminClient> | undefined;

// Server-side Supabase client with service role - bypasses RLS
// SECURITY: Only use this for trusted server-side operations, never expose to client code
// Load inside server handlers: const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
// Top-level import is safe only in other .server.ts modules - route files and *.functions.ts ship to the client bundle.
export const supabaseAdmin = new Proxy({} as ReturnType<typeof createSupabaseAdminClient>, {
  get(_, prop, receiver) {
    if (!_supabaseAdmin) _supabaseAdmin = createSupabaseAdminClient();
    return Reflect.get(_supabaseAdmin, prop, receiver);
  },
});
